code.java:
class Solution {
    public int longestPalindrome(String s){
        int[] counts=new int[128];
        for(char c:s.toCharArray())counts[c]++;
        int answer=0;
        for(int count:counts)answer+=count/2*2;
        return answer<s.length()?answer+1:answer;
    }
}

code.kotlin:
class Solution {
    fun longestPalindrome(s:String):Int{
        val counts=IntArray(128);
        for(c in s)counts[c.code]++;
        var answer=0;
        for(count in counts)answer+=count/2*2;
        return if(answer<s.length)answer+1 else answer
    }
}

